ALTER TABLE "activity_notification_preferences" ADD COLUMN "tutorial_email_mode" text DEFAULT 'once' NOT NULL;--> statement-breakpoint
ALTER TABLE "activity_notification_preferences" ADD COLUMN "tutorial_email_lead_minutes" integer DEFAULT 60 NOT NULL;--> statement-breakpoint
ALTER TABLE "activity_notification_preferences" ADD COLUMN "tutorial_email_interval_minutes" integer DEFAULT 30 NOT NULL;--> statement-breakpoint
ALTER TABLE "activity_notification_preferences" ADD CONSTRAINT "tutorial_email_schedule_check" CHECK ("activity_notification_preferences"."tutorial_email_mode" in ('once','repeat') and "activity_notification_preferences"."tutorial_email_lead_minutes" between 1 and 1440 and "activity_notification_preferences"."tutorial_email_interval_minutes" between 5 and 1440 and ("activity_notification_preferences"."tutorial_email_mode" = 'once' or ("activity_notification_preferences"."tutorial_email_interval_minutes" < "activity_notification_preferences"."tutorial_email_lead_minutes" and "activity_notification_preferences"."tutorial_email_lead_minutes" <= 12 * "activity_notification_preferences"."tutorial_email_interval_minutes")));
